        address _debtToken,
        address _governanceToken
    ) {
        collateralToken = IERC20(_collateralToken);
        debtToken = IERC20(_debtToken);
        governanceToken = IERC20(_governanceToken);
    }

    function openCDP(uint256 _collateralAmount, uint256 _debtAmount) external nonReentrant {
        require(_collateralAmount > 0, "Collateral amount must be > 0");
        require(_debtAmount > 0, "Debt amount must be > 0");

        uint256 collateralValue = _collateralAmount;
        uint256 debtValue = _debtAmount;

        require(
            (collateralValue * 100) / debtValue >= collateralizationRatio,
            "Collateralization ratio too low"
        );

        collateralToken.transferFrom(msg.sender, address(this), _collateralAmount);
        debtToken.mint(msg.sender, _debtAmount);

        cdpList[msg.sender] = CDP({
            collateralAmount: _collateralAmount,
            debtAmount: _debtAmount,
            owner: msg.sender,
            isLiquidated: false
        });

        totalCollateral += _collateralAmount;
        totalDebt += _debtAmount;

        emit CDPOpened(msg.sender, _collateralAmount, _debtAmount);
    }

    function updateCDP(uint256 _collateralAmount, uint256 _debtAmount) external nonReentrant {
        CDP storage cdp = cdpList[msg.sender];
        require(!cdp.isLiquidated, "CDP already liquidated");

        uint256 newCollateral = cdp.collateralAmount + _collateralAmount;
        uint256 newDebt = cdp.debtAmount + _debtAmount;

        require(
            (newCollateral * 100) / newDebt >= collateralizationRatio,
            "Collateralization ratio too low"
        );

        if (_collateralAmount > 0) {
            collateralToken.transferFrom(msg.sender, address(this), _collateralAmount);
            totalCollateral += _collateralAmount;
        }

        if (_debtAmount > 0) {
            debtToken.mint(msg.sender, _debtAmount);
            totalDebt += _debtAmount;
        }

        cdp.collateralAmount = newCollateral;
        cdp.debtAmount = newDebt;

        emit CDPUpdated(msg.sender, newCollateral, newDebt);
    }

